1	// hotloops -- hot inner-loop detector for baremetal RISC-V ELFs.
2	//
3	// Runs a baremetal ELF under qemu-system-{arch} with the hotloops TCG
4	// plugin (qemu_plugin/libhotloops.so) and prints a sorted table (or
5	// LLM-ready Markdown report) of detected backward branches.
6	//
7	// Usage: hotloops [opts] <elf>
8	//
9	// Options:
10	//   --arch <riscv32|riscv64|auto>   Target arch (default: auto)
11	//   --qemu <path>                   Override qemu-system binary
12	//   --plugin <path>                 Override hotloops plugin .so
13	//   --machine <name>                -M <name> (default: andes_ae350)
14	//   --cpu <spec>                    -cpu <spec>
15	//   --qemu-config <file>            -readconfig <file>
16	//   --cwd <dir>                     chdir before launching QEMU
17	//   --qemu-arg <arg>                Extra arg forwarded to QEMU (repeatable)
18	//   --limit <N>                     Top-N loops to print (default: 50)
19	//   --min-iters <N>                 Drop loops with fewer than N iters (default: 1)
20	//   --objdump <path>                Override objdump
21	//   --addr2line <path>              Override addr2line
22	//   --no-source                     Disable source file:line resolution
23	//   --raw                           Print raw plugin log, no formatting
24	//   --optimize-rvv / --no-optimize-rvv  RVV-only filter (default: on)
25	//   --llm / --no-llm                LLM Markdown report vs. plain table (default: on)
26	//   -h | --help                     Show this help
27	
28	#include "elf_syms.hpp"
29	#include "process.hpp"
30	#include "repo_root.hpp"
31	
32	#include <algorithm>
33	#include <cstdint>
34	#include <cstdio>
35	#include <cstdlib>
36	#include <cstring>
37	#include <filesystem>
38	#include <fstream>
39	#include <iostream>
40	#include <map>
41	#include <optional>
42	#include <regex>
43	#include <set>
44	#include <sstream>
45	#include <stdexcept>
46	#include <string>
47	#include <tuple>
48	#include <vector>
49	
50	#include <elf.h>
51	#include <fcntl.h>
52	#include <sys/wait.h>
53	#include <unistd.h>
54	
55	namespace fs = std::filesystem;
56	
57	// ─── TempFile ────────────────────────────────────────────────────────────────
58	
59	struct TempFile {
60	  std::string path;
61	  TempFile() {
62	    char tmpl[] = "/tmp/hotloops.XXXXXX";
63	    int fd = mkstemp(tmpl);
64	    if (fd < 0) throw std::runtime_error("mkstemp failed");
65	    close(fd);
66	    path = tmpl;
67	  }
68	  ~TempFile() { if (!path.empty()) ::unlink(path.c_str()); }
69	  TempFile(const TempFile&) = delete;
70	  TempFile& operator=(const TempFile&) = delete;
71	};
72	
73	// ─── Config ──────────────────────────────────────────────────────────────────
74	
75	struct Config {
76	  std::string arch        = "auto";
77	  std::string qemu;
78	  std::string plugin;
79	  std::string machine     = "andes_ae350";
80	  std::string cpu         = "andes-ax45mpv,vext_spec=v1.0,vlen=1024";
81	  std::string qemu_config;
82	  std::string qemu_cwd;
83	  std::vector<std::string> extra_qemu_args;
84	  int limit               = 50;
85	  int min_iters           = 1;
86	  std::string objdump;
87	  std::string addr2line_bin;
88	  bool no_source          = false;
89	  bool raw                = false;
90	  bool optimize_rvv       = true;
91	  bool llm                = true;
92	  std::string elf;
93	};
94	
95	static void usage(const char* prog) {
96	  fprintf(stderr,
97	    "Usage: %s [opts] <elf>\n\n"
98	    "  --arch <riscv32|riscv64|auto>   Target arch (default: auto)\n"
99	    "  --qemu <path>                   Override qemu-system binary\n"
100	    "  --plugin <path>                 Override plugin .so\n"
101	    "  --machine <name>                -M <name> (default: andes_ae350)\n"
102	    "  --cpu <spec>                    -cpu <spec>\n"
103	    "  --qemu-config <file>            -readconfig <file>\n"
104	    "  --cwd <dir>                     chdir before launching QEMU\n"
105	    "  --qemu-arg <arg>                Extra QEMU arg (repeatable)\n"
106	    "  --limit <N>                     Top-N loops (default: 50)\n"
107	    "  --min-iters <N>                 Drop loops with fewer iters (default: 1)\n"
108	    "  --objdump <path>                Override objdump\n"
109	    "  --addr2line <path>              Override addr2line\n"
110	    "  --no-source                     Disable source file:line resolution\n"
111	    "  --raw                           Print raw plugin output\n"
112	    "  --optimize-rvv / --no-optimize-rvv  RVV-only filter (default: on)\n"
113	    "  --llm / --no-llm                LLM report vs. table (default: on)\n"
114	    "  -h | --help                     Show this help\n",
115	    prog);
116	  exit(0);
117	}
118	
119	static Config parse_args(int argc, char** argv) {
120	  Config c;
121	  for (int i = 1; i < argc; ++i) {
122	    std::string a = argv[i];
123	    auto next = [&]() -> std::string {
124	      if (i + 1 >= argc) { fprintf(stderr, "error: %s requires an argument\n", argv[i]); exit(2); }
125	      return argv[++i];
126	    };
127	    if (a == "--arch")         c.arch         = next();
128	    else if (a == "--qemu")    c.qemu         = next();
129	    else if (a == "--plugin")  c.plugin       = next();
130	    else if (a == "--machine") c.machine      = next();
131	    else if (a == "--cpu")     c.cpu          = next();
132	    else if (a == "--qemu-config") c.qemu_config = next();
133	    else if (a == "--cwd")     c.qemu_cwd     = next();
134	    else if (a == "--qemu-arg") c.extra_qemu_args.push_back(next());
135	    else if (a == "--limit")   c.limit        = std::stoi(next());
136	    else if (a == "--min-iters") c.min_iters  = std::stoi(next());
137	    else if (a == "--objdump") c.objdump      = next();
138	    else if (a == "--addr2line") c.addr2line_bin = next();
139	    else if (a == "--no-source")    c.no_source    = true;
140	    else if (a == "--raw")          c.raw          = true;
141	    else if (a == "--optimize-rvv") c.optimize_rvv = true;
142	    else if (a == "--no-optimize-rvv") c.optimize_rvv = false;
143	    else if (a == "--llm")          c.llm          = true;
144	    else if (a == "--no-llm")       c.llm          = false;
145	    else if (a == "-h" || a == "--help") usage(argv[0]);
146	    else if (a.starts_with("-")) {
147	      fprintf(stderr, "error: unknown option: %s\n", a.c_str()); exit(2);
148	    } else {
149	      if (!c.elf.empty()) { fprintf(stderr, "error: unexpected positional arg: %s\n", a.c_str()); exit(2); }
150	      c.elf = a;
151	    }
152	  }
153	  if (c.elf.empty()) { fprintf(stderr, "error: ELF path required\n"); exit(2); }
154	  if (!fs::exists(c.elf)) { fprintf(stderr, "error: not found: %s\n", c.elf.c_str()); exit(2); }
155	  return c;
156	}
157	
158	// ─── ELF arch detection ──────────────────────────────────────────────────────
159	
160	static std::string detect_arch(const std::string& path) {
161	  std::ifstream f(path, std::ios::binary);
162	  if (!f) return "";
163	  uint8_t buf[20];
164	  f.read(reinterpret_cast<char*>(buf), 20);
165	  if (!f || buf[0] != 0x7f || buf[1] != 'E' || buf[2] != 'L' || buf[3] != 'F')
166	    return "";
167	  uint16_t e_machine = static_cast<uint16_t>(buf[18]) | (static_cast<uint16_t>(buf[19]) << 8);
168	  if (e_machine != 0xF3) return "";  // not RISC-V (EM_RISCV=243)
169	  return (buf[4] == ELFCLASS64) ? "riscv64" : "riscv32";
170	}
171	
172	// ─── Symbol lookup (delegates to elf_syms; ELF is small and OS-page-cached) ──
173	
174	static std::string sym_at(const std::string& elf, uint64_t pc) {
175	  std::string s = andes_sim::symbolize(elf, pc);
176	  if (!s.empty()) return s;
177	  char buf[20]; snprintf(buf, sizeof(buf), "0x%llx", (unsigned long long)pc);
178	  return buf;
179	}
180	
181	static std::string sym_func_at(const std::string& elf, uint64_t pc) {
182	  std::string s = andes_sim::symbolize(elf, pc);
183	  auto p = s.find('+');
184	  return (p != std::string::npos) ? s.substr(0, p) : s;
185	}
186	
187	// ─── Subprocess helpers ───────────────────────────────────────────────────────
188	
189	// Run argv with stdout+stderr redirected to /dev/null; chdir to cwd if set.
190	// Returns child exit code, 128+signal if killed, -1 on fork failure.
191	static int run_silent(const std::vector<std::string>& argv, const std::string& cwd) {
192	  if (argv.empty()) return -1;
193	  pid_t pid = fork();
194	  if (pid < 0) return -1;
195	  if (pid == 0) {
196	    if (!cwd.empty() && chdir(cwd.c_str()) != 0) _exit(127);
197	    int devnull = open("/dev/null", O_RDWR);
198	    if (devnull >= 0) {
199	      dup2(devnull, STDIN_FILENO);
200	      dup2(devnull, STDOUT_FILENO);
201	      dup2(devnull, STDERR_FILENO);
202	      if (devnull > 2) close(devnull);
203	    }
204	    std::vector<char*> cargv;
205	    cargv.reserve(argv.size() + 1);
206	    for (const auto& a : argv) cargv.push_back(const_cast<char*>(a.c_str()));
207	    cargv.push_back(nullptr);
208	    execvp(cargv[0], cargv.data());
209	    _exit(127);
210	  }
211	  int status = 0;
212	  waitpid(pid, &status, 0);
213	  if (WIFEXITED(status)) return WEXITSTATUS(status);
214	  if (WIFSIGNALED(status)) return 128 + WTERMSIG(status);
215	  return -1;
216	}
