309	// ─── Disassembly parsing ─────────────────────────────────────────────────────
310	
311	struct InsnInfo {
312	  std::string mnemonic;
313	  std::string operands;
314	};
315	
316	static std::map<uint64_t, InsnInfo> parse_disasm(const std::string& raw) {
317	  std::map<uint64_t, InsnInfo> m;
318	  std::istringstream ss(raw);
319	  // Matches: optional leading whitespace, hex digits, colon, whitespace,
320	  // then mnemonic.  Works for both GNU and LLVM objdump.
321	  static const std::regex re(R"(^\s*([0-9a-fA-F]+):\s+(\S+)(?:\s+(.*))?$)");
322	  std::string line;
323	  while (std::getline(ss, line)) {
324	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
325	      line.pop_back();
326	    std::smatch sm;
327	    if (!std::regex_match(line, sm, re)) continue;
328	    uint64_t pc;
329	    try { pc = std::stoull(sm[1], nullptr, 16); } catch (...) { continue; }
330	    std::string mn = sm[2];
331	    std::string ops = sm.size() > 3 ? sm[3].str() : "";
332	    // Trim trailing whitespace from ops.
333	    while (!ops.empty() && (ops.back() == ' ' || ops.back() == '\t')) ops.pop_back();
334	    m[pc] = {std::move(mn), std::move(ops)};
335	  }
336	  return m;
337	}
338	
339	static bool is_rvv(const std::string& mn) {
340	  if (mn.size() < 2) return false;
341	  char lo = static_cast<char>(tolower(static_cast<unsigned char>(mn[0])));
342	  return lo == 'v' && std::isalpha(static_cast<unsigned char>(mn[1]));
343	}
344	
345	struct RvvInsn { uint64_t pc; std::string mn, ops; };
346	struct CallInsn { uint64_t pc; std::string mn, target; };
347	
348	static const std::set<std::string> CALL_MN = {"jal","jalr","c.jal","c.jalr"};
349	
350	static std::vector<RvvInsn> rvv_in_range(
351	    const std::map<uint64_t, InsnInfo>& disasm,
352	    uint64_t s, uint64_t e)
353	{
354	  std::vector<RvvInsn> out;
355	  auto it = disasm.lower_bound(s);
356	  while (it != disasm.end() && it->first <= e) {
357	    if (is_rvv(it->second.mnemonic))
358	      out.push_back({it->first, it->second.mnemonic, it->second.operands});
359	    ++it;
360	  }
361	  return out;
362	}
363	
364	static std::vector<CallInsn> calls_in_range(
365	    const std::map<uint64_t, InsnInfo>& disasm,
366	    uint64_t s, uint64_t e)
367	{
368	  std::vector<CallInsn> out;
369	  static const std::regex callee_re("<([^>]+)>");
370	  auto it = disasm.lower_bound(s);
371	  while (it != disasm.end() && it->first <= e) {
372	    std::string lo = it->second.mnemonic;
373	    std::transform(lo.begin(), lo.end(), lo.begin(),
374	                   [](unsigned char c){ return tolower(c); });
375	    if (CALL_MN.count(lo)) {
376	      std::smatch m;
377	      std::string target = "(indirect)";
378	      if (std::regex_search(it->second.operands, m, callee_re))
379	        target = m[1];
380	      out.push_back({it->first, it->second.mnemonic, target});
381	    }
382	    ++it;
383	  }
384	  return out;
385	}
