387	// ─── Source line resolution ──────────────────────────────────────────────────
388	
389	static std::map<uint64_t, std::string> resolve_sources(
390	    const std::string& addr2line_bin,
391	    const std::string& elf_path,
392	    const std::vector<uint64_t>& pcs)
393	{
394	  std::map<uint64_t, std::string> result;
395	  if (addr2line_bin.empty() || pcs.empty()) return result;
396	
397	  // Build input: one hex address per line.
398	  std::string input;
399	  for (uint64_t pc : pcs) {
400	    char buf[20]; snprintf(buf, sizeof(buf), "0x%llx\n", (unsigned long long)pc);
401	    input += buf;
402	  }
403	
404	  std::string out = capture_with_stdin({addr2line_bin, "-e", elf_path}, input);
405	
406	  // One output line per input address.
407	  std::istringstream ss(out);
408	  std::string line;
409	  size_t idx = 0;
410	  while (std::getline(ss, line) && idx < pcs.size()) {
411	    while (!line.empty() && (line.back() == '\r' || line.back() == '\n'))
412	      line.pop_back();
413	    if (!line.empty() && line.find("??") == std::string::npos)
414	      result[pcs[idx]] = line;
415	    ++idx;
416	  }
417	  return result;
418	}
419	
420	static std::string src_basename(const std::string& s) {
421	  if (s.empty()) return "";
422	  // "path:line[ (extra)]" -> "basename(path):line[ ...]"
423	  auto sp = s.find(' ');
424	  std::string head = (sp != std::string::npos) ? s.substr(0, sp) : s;
425	  std::string tail = (sp != std::string::npos) ? s.substr(sp) : "";
426	  auto slash = head.rfind('/');
427	  return ((slash != std::string::npos) ? head.substr(slash + 1) : head) + tail;
428	}
429	
430	static std::pair<std::string,int> parse_file_line(const std::string& s) {
431	  if (s.empty() || s.rfind("??", 0) == 0) return {"", 0};
432	  static const std::regex re(R"(^(.+?):(\d+)(?::\d+)?(?:\s|$))");
433	  std::smatch m;
434	  if (!std::regex_search(s, m, re)) return {"", 0};
435	  return {m[1], std::stoi(m[2])};
436	}
437	
438	static std::string read_source_line(const std::string& path, int lineno) {
439	  if (path.empty() || lineno <= 0 || !fs::is_regular_file(path)) return "";
440	  std::ifstream f(path);
441	  std::string line;
442	  for (int i = 1; std::getline(f, line); ++i) {
443	    if (i == lineno) {
444	      while (!line.empty() && (line.back() == '\r' || line.back() == '\n' ||
445	                                line.back() == ' '  || line.back() == '\t'))
446	        line.pop_back();
447	      auto s = line.find_first_not_of(" \t");
448	      return (s != std::string::npos) ? line.substr(s) : line;
449	    }
450	  }
451	  return "";
452	}
